/**
 * Shared wave field.
 *
 * The exact same sum of directional sine waves is evaluated three ways:
 *  - on the CPU (to float the surf rig on the surface),
 *  - in the ocean vertex shader (to displace the water mesh),
 *  - in the ocean vertex shader again for the analytic surface normal.
 *
 * The GLSL is generated from the data below so the two always agree.
 */
import * as THREE from "three";

/** dir must be a unit [x, z] direction the crest travels along. */
export const WAVES = [
  { dir: [0.31, 0.95], amp: 1.02, k: 0.118, omega: 0.86, phase: 0.0 },
  { dir: [-0.74, 0.67], amp: 0.68, k: 0.191, omega: 1.16, phase: 1.72 },
  { dir: [0.88, -0.47], amp: 0.42, k: 0.315, omega: 1.78, phase: 3.05 },
  { dir: [-0.4, -0.92], amp: 0.24, k: 0.53, omega: 2.42, phase: 4.41 },
  { dir: [0.98, 0.2], amp: 0.13, k: 0.92, omega: 3.31, phase: 0.94 },
];

export const TOTAL_AMPLITUDE = WAVES.reduce((s, w) => s + w.amp, 0);

const f = (n) => n.toFixed(5);

/** Height of the water surface at world (x, z) at time t. */
export function waveHeight(x, z, t) {
  let h = 0;
  for (const w of WAVES) {
    h += w.amp * Math.sin(w.k * (x * w.dir[0] + z * w.dir[1]) - w.omega * t + w.phase);
  }
  return h;
}

const _n = new THREE.Vector3();

/** Analytic surface normal of the water at world (x, z) at time t. */
export function waveNormal(x, z, t, target = _n) {
  let dhx = 0;
  let dhz = 0;
  for (const w of WAVES) {
    const c = w.amp * w.k * Math.cos(w.k * (x * w.dir[0] + z * w.dir[1]) - w.omega * t + w.phase);
    dhx += c * w.dir[0];
    dhz += c * w.dir[1];
  }
  return target.set(-dhx, 1, -dhz).normalize();
}

/** GLSL implementation of the two functions above. */
export function waveGLSL() {
  const height = WAVES.map(
    (w) =>
      `\t${f(w.amp)} * sin( ${f(w.k)} * dot( p, vec2( ${f(w.dir[0])}, ${f(w.dir[1])} ) ) - ${f(
        w.omega
      )} * t + ${f(w.phase)} )`
  ).join(" +\n");

  const grad = WAVES.map(
    (w) =>
      `\t{\n\t\tfloat c = ${f(w.amp * w.k)} * cos( ${f(w.k)} * dot( p, vec2( ${f(
        w.dir[0]
      )}, ${f(w.dir[1])} ) ) - ${f(w.omega)} * t + ${f(w.phase)} );\n` +
      `\t\tdhx += c * ${f(w.dir[0])};\n\t\tdhz += c * ${f(w.dir[1])};\n\t}`
  ).join("\n");

  return `
float waveHeight( vec2 p, float t ) {
  return
${height}
  ;
}

vec3 waveNormal( vec2 p, float t ) {
  float dhx = 0.0;
  float dhz = 0.0;
${grad}
  return normalize( vec3( -dhx, 1.0, -dhz ) );
}
`;
}

/**
 * The animated ocean: a large plane displaced by the shared wave field,
 * shaded with a stylised water model (fresnel sky reflection, sun glitter,
 * crest foam and a haze fade into the horizon).
 */
import * as THREE from "three";
import { waveGLSL, TOTAL_AMPLITUDE } from "./waves.js";

const OCEAN_SIZE = 280;
const OCEAN_SEGMENTS = 264;

const vertexShader = /* glsl */ `
uniform float uTime;

varying vec3 vWorldPos;
varying vec3 vNormal;

${waveGLSL()}

void main() {
  vec4 worldPos = modelMatrix * vec4( position, 1.0 );
  float h = waveHeight( worldPos.xz, uTime );
  worldPos.y += h;

  vWorldPos = worldPos.xyz;
  vNormal = waveNormal( worldPos.xz, uTime );

  gl_Position = projectionMatrix * viewMatrix * worldPos;
}
`;

const fragmentShader = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDirection;
uniform float uTotalAmplitude;

varying vec3 vWorldPos;
varying vec3 vNormal;

float hash( vec2 p ) {
  return fract( sin( dot( p, vec2( 127.1, 311.7 ) ) ) * 43758.5453123 );
}

float noise( vec2 p ) {
  vec2 i = floor( p );
  vec2 f = fract( p );
  vec2 u = f * f * ( 3.0 - 2.0 * f );
  return mix(
    mix( hash( i ), hash( i + vec2( 1.0, 0.0 ) ), u.x ),
    mix( hash( i + vec2( 0.0, 1.0 ) ), hash( i + vec2( 1.0, 1.0 ) ), u.x ),
    u.y
  );
}

void main() {
  vec3 viewDir = normalize( cameraPosition - vWorldPos );
  vec3 sunDir = normalize( uSunDirection );

  // --- fine ripple detail on top of the big swells -------------------------
  vec2 rp = vWorldPos.xz * 1.35 + vec2( uTime * 0.32, -uTime * 0.19 );
  float n0 = noise( rp );
  float nx = noise( rp + vec2( 0.17, 0.0 ) );
  float nz = noise( rp + vec2( 0.0, 0.17 ) );
  vec3 normal = normalize( vNormal + vec3( ( n0 - nx ) * 1.35, 0.0, ( n0 - nz ) * 1.35 ) );

  // --- water body colour ---------------------------------------------------
  float depthMix = clamp( vWorldPos.y / uTotalAmplitude * 0.5 + 0.55, 0.0, 1.0 );
  vec3 water = mix( vec3( 0.027, 0.180, 0.322 ), vec3( 0.098, 0.451, 0.608 ), depthMix );

  // --- sky reflection through fresnel -------------------------------------
  float fresnel = pow( 1.0 - clamp( dot( normal, viewDir ), 0.0, 1.0 ), 4.0 );
  fresnel = mix( 0.055, 1.0, fresnel );
  vec3 skyRef = mix( vec3( 0.639, 0.788, 0.878 ), vec3( 0.235, 0.494, 0.780 ), clamp( normal.y * 1.25, 0.0, 1.0 ) );
  vec3 color = mix( water, skyRef, fresnel );

  // --- sun glitter ---------------------------------------------------------
  vec3 halfVec = normalize( sunDir + viewDir );
  float ndh = max( dot( normal, halfVec ), 0.0 );
  float sparkle = noise( vWorldPos.xz * 6.0 + vec2( uTime * 1.1, uTime * 0.7 ) );
  color += vec3( 1.0, 0.925, 0.780 ) * pow( ndh, 320.0 ) * 3.2;
  color += vec3( 1.0, 0.902, 0.706 ) * pow( ndh, 34.0 ) * ( 0.10 + sparkle * 0.22 );

  // --- foam on the crests --------------------------------------------------
  float crest = smoothstep( 0.30, 1.05, vWorldPos.y / uTotalAmplitude );
  float foamTex = noise( vWorldPos.xz * 2.35 + vec2( uTime * 0.45, uTime * 0.32 ) ) * 0.65
                + noise( vWorldPos.xz * 5.5 - vec2( uTime * 0.3, uTime * 0.42 ) ) * 0.35;
  float foam = smoothstep( 0.32, 0.86, crest * ( 0.45 + foamTex * 1.05 ) );
  float streak = smoothstep( 0.55, 1.0, noise( vWorldPos.xz * vec2( 1.4, 7.0 ) + vec2( uTime * 0.5, 0.0 ) ) ) * crest;
  foam = clamp( foam * 0.9 + streak * 0.28, 0.0, 1.0 );
  color = mix( color, vec3( 0.925, 0.965, 0.984 ), foam * 0.88 );

  // --- haze toward the horizon -------------------------------------------
  float dist = length( cameraPosition - vWorldPos );
  color = mix( color, vec3( 0.741, 0.855, 0.918 ), smoothstep( 55.0, 210.0, dist ) );

  gl_FragColor = vec4( color, 1.0 );
}
`;

export function createOcean(scene, sunDirection) {
  const geometry = new THREE.PlaneGeometry(OCEAN_SIZE, OCEAN_SIZE, OCEAN_SEGMENTS, OCEAN_SEGMENTS);
  geometry.rotateX(-Math.PI / 2);

  const material = new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    uniforms: {
      uTime: { value: 0 },
      uSunDirection: { value: sunDirection.clone() },
      uTotalAmplitude: { value: TOTAL_AMPLITUDE },
    },
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  scene.add(mesh);

  return {
    mesh,
    update(t) {
      material.uniforms.uTime.value = t;
    },
  };
}

/**
 * Sky dome with sun glow, drifting stylised clouds and distant seabirds.
 */
import * as THREE from "three";

const vertexShader = /* glsl */ `
varying vec3 vDirection;

void main() {
  vDirection = normalize( position );
  gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}
`;

const fragmentShader = /* glsl */ `
uniform vec3 uSunDirection;
varying vec3 vDirection;

void main() {
  vec3 dir = normalize( vDirection );
  float h = clamp( dir.y * 1.12 + 0.055, 0.0, 1.0 );

  // deep blue overhead fading to a pale, warm haze at the horizon
  vec3 color = mix( vec3( 0.843, 0.918, 0.965 ), vec3( 0.129, 0.396, 0.729 ), pow( h, 0.70 ) );

  float sunDot = max( dot( dir, normalize( uSunDirection ) ), 0.0 );
  color += vec3( 1.0, 0.851, 0.596 ) * pow( sunDot, 6.0 ) * 0.30;
  color += vec3( 1.0, 0.949, 0.812 ) * pow( sunDot, 160.0 ) * 0.85;
  color += vec3( 1.0, 0.988, 0.933 ) * smoothstep( 0.9992, 0.9998, sunDot ) * 2.2;

  // haze band exactly where the ocean meets the sky
  color = mix( color, vec3( 0.788, 0.886, 0.937 ), smoothstep( 0.155, 0.0, abs( dir.y ) ) );

  gl_FragColor = vec4( color, 1.0 );
}
`;

function createCloud(material) {
  const group = new THREE.Group();
  const puffs = 5 + Math.floor(Math.random() * 4);
  for (let i = 0; i < puffs; i++) {
    const puff = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), material);
    puff.position.set(
      (Math.random() - 0.5) * 7.5,
      (Math.random() - 0.5) * 1.5,
      (Math.random() - 0.5) * 3.0
    );
    const s = 1.7 + Math.random() * 2.1;
    puff.scale.set(s * (1.15 + Math.random() * 0.6), s * 0.55, s);
    group.add(puff);
  }
  return group;
}

function createBird(material) {
  const bird = new THREE.Group();
  const wingGeo = new THREE.PlaneGeometry(2.1, 0.62, 3, 1);
  const positions = wingGeo.attributes.position;
  for (let i = 0; i < positions.count; i++) {
    const x = positions.getX(i);
    positions.setZ(i, Math.abs(x) * 0.34); // gentle dihedral curve
    positions.setY(i, positions.getY(i) * (1.0 - Math.abs(x) * 0.22));
  }
  wingGeo.computeVertexNormals();

  const left = new THREE.Mesh(wingGeo, material);
  left.position.x = -1.02;
  const right = new THREE.Mesh(wingGeo, material);
  right.position.x = 1.02;
  right.scale.x = -1;

  const body = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), material);
  body.scale.set(1, 0.8, 1.9);

  bird.add(left, right, body);
  bird.userData.wings = [left, right];
  return bird;
}

export function createSky(scene, sunDirection) {
  const domeMaterial = new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    uniforms: { uSunDirection: { value: sunDirection.clone() } },
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(430, 32, 20), domeMaterial);
  dome.frustumCulled = false;
  dome.renderOrder = -1;
  scene.add(dome);

  // ---- clouds -------------------------------------------------------------
  const cloudMaterial = new THREE.MeshLambertMaterial({
    color: 0xfdfdff,
    transparent: true,
    opacity: 0.92,
    depthWrite: true,
  });
  const clouds = [];
  for (let i = 0; i < 11; i++) {
    const cloud = createCloud(cloudMaterial);
    const angle = (i / 11) * Math.PI * 2 + Math.random() * 0.5;
    const radius = 120 + Math.random() * 150;
    cloud.position.set(
      Math.cos(angle) * radius,
      26 + Math.random() * 46,
      Math.sin(angle) * radius
    );
    cloud.rotation.y = Math.random() * Math.PI;
    cloud.userData.speed = 0.6 + Math.random() * 0.9;
    clouds.push(cloud);
    scene.add(cloud);
  }

  // ---- distant seabirds ---------------------------------------------------
  const birdMaterial = new THREE.MeshBasicMaterial({
    color: 0x4a6072,
    transparent: true,
    opacity: 0.55,
    side: THREE.DoubleSide,
  });
  const birds = [];
  for (let i = 0; i < 7; i++) {
    const bird = createBird(birdMaterial);
    const radius = 55 + Math.random() * 65;
    bird.userData.radius = radius;
    bird.userData.angle = Math.random() * Math.PI * 2;
    bird.userData.speed = (0.035 + Math.random() * 0.035) * (Math.random() < 0.5 ? -1 : 1);
    bird.userData.height = 12 + Math.random() * 16;
    bird.userData.phase = Math.random() * Math.PI * 2;
    bird.scale.setScalar(0.7 + Math.random() * 0.8);
    birds.push(bird);
    scene.add(bird);
  }

  return {
    dome,
    update(t, dt) {
      for (const cloud of clouds) {
        cloud.position.x += cloud.userData.speed * dt;
        if (cloud.position.x > 330) cloud.position.x = -330;
      }
      for (const bird of birds) {
        const u = bird.userData;
        u.angle += u.speed * dt;
        bird.position.set(
          Math.cos(u.angle) * u.radius,
          u.height + Math.sin(t * 0.5 + u.phase) * 1.6,
          Math.sin(u.angle) * u.radius
        );
        bird.rotation.y = -u.angle + (u.speed > 0 ? -Math.PI / 2 : Math.PI / 2);
        const flap = Math.sin(t * 4.2 + u.phase) * 0.62;
        u.wings[0].rotation.x = flap;
        u.wings[1].rotation.x = flap;
      }
    },
  };
}

/**
 * Procedural textures generated on a canvas at runtime (no external assets).
 */
import * as THREE from "three";

/** Soft round sprite with a radial alpha falloff. */
export function softCircleTexture(size = 128, inner = 0.0) {
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext("2d");
  const g = ctx.createRadialGradient(
    size / 2,
    size / 2,
    size * 0.5 * inner,
    size / 2,
    size / 2,
    size * 0.5
  );
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.45, "rgba(255,255,255,0.55)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(canvas);
}

/** Irregular foam patch made of overlapping soft blobs. */
export function foamTexture(size = 256, blobs = 90) {
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext("2d");
  for (let i = 0; i < blobs; i++) {
    const x = Math.random() * size;
    const y = Math.random() * size;
    const r = size * (0.02 + Math.random() * 0.11);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    const a = 0.12 + Math.random() * 0.45;
    g.addColorStop(0, `rgba(255,255,255,${a})`);
    g.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
  return texture;
}

/**
 * The surfing pelican: a stylised bird built from primitives riding a
 * surfboard. The whole rig is driven by the shared wave field so it floats
 * and tilts on the moving water surface.
 */
import * as THREE from "three";
import { waveHeight, waveNormal } from "./waves.js";
import { softCircleTexture, foamTexture } from "./textures.js";

const BOARD_HALF_LENGTH = 1.95;
const BOARD_HALF_WIDTH = 0.62;
const BOARD_TOP = 0.17;
const PELICAN_SCALE = 0.62;
const FOOT_Y = -1.15; // in pelican local space

// ---------------------------------------------------------------- materials
function materials() {
  return {
    body: new THREE.MeshStandardMaterial({ color: 0xf7f2e8, roughness: 0.78, metalness: 0.0 }),
    bodyShade: new THREE.MeshStandardMaterial({ color: 0xe6e2d6, roughness: 0.82, metalness: 0.0 }),
    wing: new THREE.MeshStandardMaterial({ color: 0xece7db, roughness: 0.82, metalness: 0.0 }),
    wingTip: new THREE.MeshStandardMaterial({ color: 0xb9c2ca, roughness: 0.85, metalness: 0.0 }),
    beak: new THREE.MeshStandardMaterial({ color: 0xf2a83f, roughness: 0.46, metalness: 0.03 }),
    pouch: new THREE.MeshStandardMaterial({ color: 0xe07f27, roughness: 0.52, metalness: 0.02 }),
    leg: new THREE.MeshStandardMaterial({ color: 0xe58a2c, roughness: 0.55, metalness: 0.02 }),
    eye: new THREE.MeshStandardMaterial({ color: 0x191c24, roughness: 0.18, metalness: 0.12 }),
    glint: new THREE.MeshBasicMaterial({ color: 0xffffff }),
    board: new THREE.MeshStandardMaterial({ color: 0xeef3f6, roughness: 0.34, metalness: 0.06 }),
    stripe: new THREE.MeshStandardMaterial({ color: 0xe2503c, roughness: 0.42, metalness: 0.04 }),
    fin: new THREE.MeshStandardMaterial({ color: 0x2f6f8f, roughness: 0.45, metalness: 0.05 }),
  };
}

// ------------------------------------------------------------------- surfboard
function createBoard(mats) {
  const group = new THREE.Group();

  const shape = new THREE.Shape();
  const L = BOARD_HALF_LENGTH;
  const W = BOARD_HALF_WIDTH;
  shape.moveTo(0, L);
  shape.bezierCurveTo(W * 0.5, L * 0.74, W, L * 0.26, W, 0.05);
  shape.bezierCurveTo(W, -L * 0.5, W * 0.66, -L * 0.94, 0, -L);
  shape.bezierCurveTo(-W * 0.66, -L * 0.94, -W, -L * 0.5, -W, 0.05);
  shape.bezierCurveTo(-W, L * 0.26, -W * 0.5, L * 0.74, 0, L);

  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: 0.07,
    bevelEnabled: true,
    bevelThickness: 0.13,
    bevelSize: 0.12,
    bevelSegments: 5,
    curveSegments: 30,
  });
  geometry.rotateX(Math.PI / 2); // nose points toward +Z
  geometry.computeBoundingBox();
  geometry.translate(
    0,
    -(geometry.boundingBox.min.y + geometry.boundingBox.max.y) / 2,
    0
  );

  const board = new THREE.Mesh(geometry, mats.board);
  group.add(board);

  // deck stripe + tail pad
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.035, 2.35), mats.stripe);
  stripe.position.set(0, BOARD_TOP + 0.012, 0.16);
  group.add(stripe);

  const pad = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.035, 0.62), mats.fin);
  pad.position.set(0, BOARD_TOP + 0.012, -1.12);
  group.add(pad);

  // fin under the tail
  const fin = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.34, 0.52), mats.fin);
  fin.position.set(0, -0.2, -1.28);
  fin.rotation.x = -0.22;
  group.add(fin);

  return group;
}

// --------------------------------------------------------------------- pelican
function createPelican(mats) {
  const pelican = new THREE.Group();

  // ---- body ---------------------------------------------------------------
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 28), mats.body);
  body.position.set(0, 0.3, 0);
  body.scale.set(1.02, 0.94, 1.5);
  pelican.add(body);

  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.86, 28, 20), mats.body);
  chest.position.set(0, 0.16, 0.72);
  chest.scale.set(1, 0.94, 1);
  pelican.add(chest);

  const tail = new THREE.Mesh(new THREE.SphereGeometry(1, 22, 16), mats.bodyShade);
  tail.position.set(0, 0.46, -1.52);
  tail.scale.set(0.48, 0.15, 0.78);
  tail.rotation.x = 0.3;
  pelican.add(tail);

  // ---- neck ---------------------------------------------------------------
  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0.72, 0.92),
    new THREE.Vector3(0, 1.48, 0.82),
    new THREE.Vector3(0, 2.12, 1.12),
    new THREE.Vector3(0, 2.4, 1.42),
  ]);
  const neck = new THREE.Mesh(new THREE.TubeGeometry(neckCurve, 30, 0.33, 14, false), mats.body);
  pelican.add(neck);

  // ---- head (rotates as one unit) ----------------------------------------
  const head = new THREE.Group();
  head.position.set(0, 2.62, 1.52);
  pelican.add(head);

  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.52, 30, 22), mats.body);
  skull.scale.set(0.96, 1.02, 1.16);
  head.add(skull);

  // upper mandible: long, tapered, slightly drooping at the tip
  const mandible = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.15, 1.5, 14), mats.beak);
  mandible.geometry.rotateX(Math.PI / 2);
  mandible.position.set(0, 0.05, 1.16);
  mandible.rotation.x = -0.075;
  head.add(mandible);

  const ridge = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.075, 1.12), mats.beak);
  ridge.position.set(0, 0.17, 1.06);
  ridge.rotation.x = -0.13;
  head.add(ridge);

  // the pouch under the beak
  const pouch = new THREE.Mesh(new THREE.SphereGeometry(1, 26, 20), mats.pouch);
  pouch.position.set(0, -0.2, 0.86);
  pouch.scale.set(0.31, 0.33, 0.72);
  pouch.rotation.x = 0.16;
  head.add(pouch);

  // eyes
  const eyes = [];
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.098, 16, 12), mats.eye);
    eye.position.set(side * 0.3, 0.2, 0.4);
    head.add(eye);
    eyes.push(eye);

    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.033, 10, 8), mats.glint);
    glint.position.set(side * 0.335, 0.235, 0.475);
    head.add(glint);
  }

  // swept-back crest feathers
  for (let i = 0; i < 3; i++) {
    const feather = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.5, 8), mats.bodyShade);
    feather.position.set((i - 1) * 0.12, 0.28 - i * 0.03, -0.42);
    feather.rotation.x = -1.95;
    feather.rotation.z = (i - 1) * 0.25;
    feather.scale.set(1, 1, 0.32);
    head.add(feather);
  }

  // ---- wings --------------------------------------------------------------
  const wings = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.78, 0.66, 0.1);
    pelican.add(shoulder);

    const inner = new THREE.Mesh(new THREE.SphereGeometry(1, 26, 18), mats.wing);
    inner.position.set(side * 0.66, 0, -0.16);
    inner.scale.set(0.78, 0.17, 1.05);
    shoulder.add(inner);

    const outer = new THREE.Group();
    outer.position.set(side * 1.32, 0.16, -0.78);
    shoulder.add(outer);

    const mid = new THREE.Mesh(new THREE.SphereGeometry(1, 22, 16), mats.wing);
    mid.position.set(side * 0.32, 0, -0.34);
    mid.scale.set(0.62, 0.13, 0.86);
    outer.add(mid);

    const tip = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), mats.wingTip);
    tip.position.set(side * 0.52, -0.02, -0.94);
    tip.scale.set(0.42, 0.1, 0.66);
    tip.rotation.y = side * 0.32;
    outer.add(tip);

    wings.push({ shoulder, outer, side });
  }

  // ---- legs and webbed feet ------------------------------------------------
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.115, 0.1, 0.5, 12), mats.leg);
    leg.position.set(side * 0.36, -0.88, 0.1);
    leg.rotation.z = side * 0.16;
    pelican.add(leg);

    const foot = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 10), mats.leg);
    foot.position.set(side * 0.44, FOOT_Y + 0.04, 0.3);
    foot.scale.set(0.23, 0.055, 0.38);
    foot.rotation.y = side * 0.22;
    pelican.add(foot);
  }

  return { group: pelican, head, eyes, wings, pouch };
}

// ------------------------------------------------------------------ the rig
export function createSurfRig(scene) {
  const mats = materials();
  const group = new THREE.Group();
  scene.add(group);

  const board = createBoard(mats);
  group.add(board);

  const pelican = createPelican(mats);
  pelican.group.scale.setScalar(PELICAN_SCALE);
  pelican.group.position.y = BOARD_TOP - FOOT_Y * PELICAN_SCALE;
  pelican.group.rotation.x = -0.07;
  group.add(pelican.group);

  // soft contact shadow and foam collar on the water surface
  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({
    map: softCircleTexture(128),
    color: 0x0d2c4c,
    transparent: true,
    opacity: 0.3,
    depthWrite: false,
  }));
  shadow.geometry.rotateX(-Math.PI / 2);
  shadow.position.y = -0.16;
  shadow.scale.set(2.6, 1, 5.2);
  shadow.renderOrder = 1;
  group.add(shadow);

  const foamMap = foamTexture(256, 110);
  const collar = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({
    map: foamMap,
    color: 0xf2fbff,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  }));
  collar.geometry.rotateX(-Math.PI / 2);
  collar.position.y = -0.11;
  collar.scale.set(2.1, 1, 4.4);
  collar.renderOrder = 2;
  group.add(collar);

  const normal = new THREE.Vector3();
  const noseWorld = new THREE.Vector3();

  return {
    group,
    pelican,
    /** World position of the board nose, used to spawn spray. */
    nosePosition(target = noseWorld) {
      return target.set(0, 0, BOARD_HALF_LENGTH * 0.92).applyMatrix4(group.matrixWorld);
    },
    update(t, dt) {
      // ride the surface
      const h = waveHeight(0, 0, t);
      waveNormal(0, 0, t, normal);
      group.position.set(0, h + 0.2, 0);
      group.rotation.order = "YXZ";
      group.rotation.set(Math.asin(normal.z), Math.sin(t * 0.13) * 0.12, -Math.asin(normal.x));

      // ---- pelican life ---------------------------------------------------
      const flap = Math.sin(t * 1.55);
      for (const wing of pelican.wings) {
        const s = wing.side;
        wing.shoulder.rotation.z = -s * (0.2 + flap * 0.34);
        wing.shoulder.rotation.x = Math.sin(t * 1.55 + 0.5) * 0.14 - 0.05;
        wing.outer.rotation.z = -s * Math.sin(t * 1.55 - 0.55) * 0.36;
        wing.outer.rotation.x = Math.sin(t * 1.55 - 1.1) * 0.18;
      }

      pelican.group.position.y =
        BOARD_TOP - FOOT_Y * PELICAN_SCALE + Math.sin(t * 1.55) * 0.045;
      pelican.group.rotation.z = Math.sin(t * 0.72) * 0.05;
      pelican.group.rotation.x = -0.07 + Math.sin(t * 0.9) * 0.035;

      pelican.head.rotation.y = Math.sin(t * 0.33) * 0.3 + Math.sin(t * 0.17) * 0.14;
      pelican.head.rotation.x = Math.sin(t * 0.47) * 0.11 - 0.03;
      pelican.head.rotation.z = Math.sin(t * 0.29) * 0.07;

      pelican.pouch.scale.y = 0.33 + Math.sin(t * 2.2) * 0.018;

      // occasional blink
      const blink = Math.pow(Math.max(0, Math.sin(t * 0.78)), 60);
      for (const eye of pelican.eyes) eye.scale.y = 1 - blink * 0.92;

      // foam texture drift
      foamMap.offset.y = (-t * 0.22) % 1;
      collar.material.opacity = 0.42 + Math.sin(t * 1.9) * 0.09;
    },
  };
}

