/**
 * Water spray kicked up by the board and the foamy wake it leaves behind.
 */
import * as THREE from "three";
import { softCircleTexture, foamTexture } from "./textures.js";

const PARTICLE_COUNT = 560;

export function createSpray(scene) {
  const positions = new Float32Array(PARTICLE_COUNT * 3);
  const alphas = new Float32Array(PARTICLE_COUNT);
  const sizes = new Float32Array(PARTICLE_COUNT);
  const velocities = new Float32Array(PARTICLE_COUNT * 3);
  const life = new Float32Array(PARTICLE_COUNT);
  const maxLife = new Float32Array(PARTICLE_COUNT);

  for (let i = 0; i < PARTICLE_COUNT; i++) {
    positions[i * 3 + 1] = -9999;
    maxLife[i] = 1;
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("aAlpha", new THREE.BufferAttribute(alphas, 1));
  geometry.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: softCircleTexture(64) },
      uColor: { value: new THREE.Color(1, 1, 1) },
      uPixelScale: { value: 700 },
    },
    vertexShader: /* glsl */ `
      attribute float aAlpha;
      attribute float aSize;
      uniform float uPixelScale;
      varying float vAlpha;

      void main() {
        vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );
        gl_PointSize = aSize * uPixelScale / max( 0.35, -mvPosition.z );
        vAlpha = aAlpha;
        gl_Position = projectionMatrix * mvPosition;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform sampler2D uMap;
      uniform vec3 uColor;
      varying float vAlpha;

      void main() {
        float a = texture2D( uMap, gl_PointCoord ).a * vAlpha;
        if ( a < 0.01 ) discard;
        gl_FragColor = vec4( uColor, a );
      }
    `,
    transparent: true,
    depthWrite: false,
  });

  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  points.renderOrder = 3;
  scene.add(points);

  let cursor = 0;
  let spawnAccumulator = 0;

  function spawn(origin, backDir) {
    const i = cursor;
    cursor = (cursor + 1) % PARTICLE_COUNT;

    positions[i * 3] = origin.x + (Math.random() - 0.5) * 0.75;
    positions[i * 3 + 1] = origin.y + Math.random() * 0.25;
    positions[i * 3 + 2] = origin.z + (Math.random() - 0.5) * 0.75;

    const speed = 1.4 + Math.random() * 3.6;
    velocities[i * 3] = backDir.x * speed + (Math.random() - 0.5) * 1.5;
    velocities[i * 3 + 1] = 1.4 + Math.random() * 3.2;
    velocities[i * 3 + 2] = backDir.z * speed + (Math.random() - 0.5) * 1.5;

    life[i] = 0;
    maxLife[i] = 0.55 + Math.random() * 0.75;
    sizes[i] = 0.12 + Math.random() * 0.3;
    alphas[i] = 0;
  }

  const backDir = new THREE.Vector3();

  return {
    points,
    setPixelScale(scale) {
      material.uniforms.uPixelScale.value = scale;
    },
    update(dt, origin, rigQuaternion) {
      backDir.set(0, 0, -1).applyQuaternion(rigQuaternion);

      spawnAccumulator += dt * 240;
      while (spawnAccumulator >= 1) {
        spawn(origin, backDir);
        spawnAccumulator -= 1;
      }

      for (let i = 0; i < PARTICLE_COUNT; i++) {
        if (life[i] >= maxLife[i]) {
          alphas[i] = 0;
          positions[i * 3 + 1] = -9999;
          continue;
        }
        life[i] += dt;
        const t = life[i] / maxLife[i];

        velocities[i * 3 + 1] -= 8.6 * dt;
        positions[i * 3] += velocities[i * 3] * dt;
        positions[i * 3 + 1] += velocities[i * 3 + 1] * dt;
        positions[i * 3 + 2] += velocities[i * 3 + 2] * dt;

        alphas[i] = Math.min(1, t * 6) * (1 - t) * 0.85;
      }

      geometry.attributes.position.needsUpdate = true;
      geometry.attributes.aAlpha.needsUpdate = true;
      geometry.attributes.aSize.needsUpdate = true;
    },
  };
}

/** Foamy trail that scrolls backwards behind the board. */
export function createWake(rigGroup) {
  const map = foamTexture(256, 130);
  map.repeat.set(1.4, 1.8);

  const material = new THREE.MeshBasicMaterial({
    map,
    color: 0xeaf7ff,
    transparent: true,
    opacity: 0.36,
    depthWrite: false,
  });

  const wake = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), material);
  wake.geometry.rotateX(-Math.PI / 2);
  wake.position.set(0, -0.12, -3.1);
  wake.scale.set(2.4, 1, 6.2);
  wake.renderOrder = 1;
  rigGroup.add(wake);

  return {
    wake,
    update(t) {
      map.offset.y = (t * 0.34) % 1;
      material.opacity = 0.3 + Math.sin(t * 1.4) * 0.06;
    },
  };
}

/**
 * Surfing Pelican — an animated, non-interactive 3D vignette.
 *
 * A pelican rides the swell on a surfboard while the camera drifts slowly
 * around it. Everything is procedural: no models, no textures, no network.
 */
import * as THREE from "three";
import { createOcean } from "./src/ocean.js";
import { createSky } from "./src/sky.js";
import { createSurfRig } from "./src/pelican.js";
import { createSpray, createWake } from "./src/effects.js";

const SUN_DIRECTION = new THREE.Vector3(-0.52, 0.4, -0.72).normalize();

// ------------------------------------------------------------------ renderer
const container = document.getElementById("app");

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

// --------------------------------------------------------------------- scene
const scene = new THREE.Scene();
scene.fog = null;

const camera = new THREE.PerspectiveCamera(
  42,
  window.innerWidth / window.innerHeight,
  0.5,
  1200
);
camera.position.set(4, 6, 15);

// -------------------------------------------------------------------- lights
const sun = new THREE.DirectionalLight(0xfff1d6, 2.7);
sun.position.copy(SUN_DIRECTION).multiplyScalar(70);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 30;
sun.shadow.camera.far = 160;
sun.shadow.camera.left = -9;
sun.shadow.camera.right = 9;
sun.shadow.camera.top = 9;
sun.shadow.camera.bottom = -9;
sun.shadow.bias = -0.0007;
sun.shadow.normalBias = 0.035;
scene.add(sun);
scene.add(sun.target);

const fill = new THREE.DirectionalLight(0x9dc6ee, 0.85);
fill.position.set(28, 18, 34);
scene.add(fill);

const hemi = new THREE.HemisphereLight(0xa9d8ff, 0x1c5c8c, 1.25);
scene.add(hemi);

// ------------------------------------------------------------------- content
const sky = createSky(scene, SUN_DIRECTION);
const ocean = createOcean(scene, SUN_DIRECTION);
const rig = createSurfRig(scene);
const spray = createSpray(scene);
const wake = createWake(rig.group);

// shadows only for the solid parts of the rig
rig.group.traverse((obj) => {
  if (obj.isMesh && obj.material && obj.material.transparent !== true) {
    obj.castShadow = true;
    obj.receiveShadow = true;
  }
});

// -------------------------------------------------------------------- camera
const lookTarget = new THREE.Vector3(0, 2.6, 0);

function updateCamera(t) {
  const azimuth = 0.34 + Math.sin(t * 0.052) * 0.38 + Math.sin(t * 0.021) * 0.16;
  const distance = 15.2 + Math.sin(t * 0.043) * 1.7;
  const height = 5.9 + Math.sin(t * 0.128) * 0.6 + Math.sin(t * 0.071) * 0.45;

  camera.position.set(
    Math.sin(azimuth) * distance,
    height + rig.group.position.y * 0.35,
    Math.cos(azimuth) * distance
  );

  lookTarget.set(
    Math.sin(t * 0.09) * 0.5,
    2.55 + rig.group.position.y * 0.55 + Math.sin(t * 0.11) * 0.3,
    0.2
  );
  camera.lookAt(lookTarget);
}

// -------------------------------------------------------------------- resize
function updatePixelScale() {
  const fovRad = THREE.MathUtils.degToRad(camera.fov);
  spray.setPixelScale(renderer.domElement.height / (2 * Math.tan(fovRad * 2)));
}

function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  updatePixelScale();
}
window.addEventListener("resize", onResize);
updatePixelScale();

// ------------------------------------------------------------------- animate
const clock = new THREE.Clock();
const nose = new THREE.Vector3();

renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  ocean.update(t);
  sky.update(t, dt);
  rig.update(t, dt);
  wake.update(t);

  rig.nosePosition(nose);
  spray.update(dt, nose, rig.group.quaternion);

  updateCamera(t);
  renderer.render(scene, camera);
});

