  const shoulder = new THREE.Group();
  shoulder.position.set(side * 0.7, 0.62, 0.16);
  pelican.add(shoulder);

  const inner = new THREE.Mesh(new THREE.SphereGeometry(1, 26, 18), mats.wing);
