// Dev-only helper: screenshots a running page via the Chrome DevTools protocol.
// Usage: node smoke/cdp-shot.mjs <ws-url-of-page> <out.png> <delayMs>
import { writeFileSync } from "node:fs";

const [, , targetUrl, outPath, delayArg] = process.argv;
const delay = Number(delayArg || 3000);

const list = await fetch("http://127.0.0.1:9333/json/list").then((r) => r.json());
const page = list.find((t) => t.type === "page" && t.url.includes(targetUrl));
if (!page) {
  console.error("no page target for", targetUrl, list.map((t) => t.url));
  process.exit(1);
}

const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const logs = [];

function send(method, params = {}) {
  const msgId = ++id;
  ws.send(JSON.stringify({ id: msgId, method, params }));
  return new Promise((res) => pending.set(msgId, res));
}

ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg.result);
    pending.delete(msg.id);
  } else if (msg.method === "Runtime.consoleAPICalled") {
    logs.push(`[${msg.params.type}] ${msg.params.args.map((a) => a.value ?? a.description).join(" ")}`);
  } else if (msg.method === "Runtime.exceptionThrown") {
    logs.push(`[exception] ${JSON.stringify(msg.params.exceptionDetails)}`);
  }
};

await new Promise((res) => (ws.onopen = res));
await send("Runtime.enable");
await send("Page.enable");

await new Promise((res) => setTimeout(res, delay));

const shot = await send("Page.captureScreenshot", { format: "png", fromSurface: true });
writeFileSync(outPath, Buffer.from(shot.data, "base64"));

const perf = await send("Runtime.evaluate", {
  expression: `JSON.stringify({
    title: document.title,
    canvas: !!document.querySelector('canvas'),
    w: document.querySelector('canvas')?.width,
    h: document.querySelector('canvas')?.height
  })`,
  returnByValue: true,
});
console.log("page:", perf.result.value);
console.log("console messages:\n" + (logs.join("\n") || "(none)"));
ws.close();
console.log("saved", outPath);

